(function(E){ const x = E["mkt-m3"] = E["mkt-m3"] || {units:{}}; x.units["mkt-11"] = {"grammar":{"id":"c-mkt-11-g","level":"B1","course":"marketing","unit":"mkt-11","title":"The background of a story: the past perfect (had + past participle)","titleTr":"Bir hikâyenin arka planı: past perfect (had + üçüncü hâl)","titleFa":"پیش‌زمینه‌ی داستان: ماضی بعید (had با اسم مفعول)","formsTable":{"headers":{"en":["Earlier (background): past perfect","Main event: past simple"],"tr":["Daha önce (arka plan): past perfect","Ana olay: past simple"],"fa":["قبل‌تر (پیش‌زمینه): ماضی بعید","اتفاق اصلی: گذشته‌ی ساده"]},"rows":[["The hotels had bought towels from three suppliers.","Then they chose us."],["Housekeeping had complained for years.","So the buyer looked for a new supplier."],["They had washed the samples fifty times.","Then they signed the contract."]]},"wrong":"Before they signed, they have washed the samples fifty times.","right":"Before they signed, they had washed the samples fifty times.","blank":{"sentence":"Before us, the hotels ___ from three different suppliers.","word":"had bought","distractors":["have bought","had buy"]},"wrong2":"The first towels had not even arrive yet.","right2":"The first towels had not even arrived yet.","blank2":{"sentence":"Housekeeping had ___ about thin towels for years.","word":"complained","distractors":["complain","complaining"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Main events of the story: past simple.","tr":"Hikâyenin ana olayları: past simple.","fa":"برای اتفاق‌های اصلی داستان، گذشته‌ی ساده می‌آید.","ex":"They chose us in March."},{"en":"Earlier background: had + past participle.","tr":"Daha önceki arka plan: had + üçüncü hâl.","fa":"برای پیش‌زمینه‌ی قبل‌تر، had و اسم مفعول می‌آید.","ex":"They had bought from three suppliers."},{"en":"Use it only where the order matters.","tr":"Sadece sıralamanın önemli olduğu yerde kullan.","fa":"فقط جایی به کارش ببر که ترتیب مهم است.","ex":"They had tested the samples before they signed."}],"test":{"en":"Did this happen before another past event in your story? Then use had + past participle.","tr":"Bu, hikâyendeki başka bir geçmiş olaydan önce mi oldu? O zaman had + üçüncü hâl kullan.","fa":"این اتفاق قبل از اتفاق دیگری در داستانت افتاده؟ پس had و اسم مفعول بیاور."},"contrast":{"en":"Turkish has the same idea in \"-mişti\" (almışlardı) and Persian in the past perfect («خریده بودند»), so the meaning is familiar. The trap is the English form: had + past participle, never had + base verb.","tr":"Türkçede aynı anlam \"-mişti\" ile verilir (almışlardı), yani fikir tanıdık. Tuzak İngilizce biçimde: had + üçüncü hâl, asla had + yalın fiil değil.","fa":"فارسی همین معنا را با ماضی بعید دارد («خریده بودند»)، پس ایده آشناست. تله در شکل انگلیسی است: had با اسم مفعول، هرگز had با فعل ساده."}},"errorWatch":[{"find":["had buy","had wash","had complain","had arrive","had sign the","before they signed, they have","before we signed, we have"],"fix":{"en":"Past perfect = had + past participle: \"had bought\", \"had washed\", \"had arrived\".","tr":"Past perfect = had + üçüncü hâl: \"had bought\", \"had washed\", \"had arrived\".","fa":"ماضی بعید یعنی had و اسم مفعول: «had bought»، «had washed»، «had arrived»."}}]},"b2":{"id":"c-mkt-11-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-11","title":"Reporting what a client agreed: agree to, ask someone not to, recommend -ing","titleTr":"Müşterinin neyi kabul ettiğini aktarmak: agree to, ask someone not to, recommend -ing","titleFa":"گزارش توافق‌های مشتری: agree to، ask someone not to، recommend -ing","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Yapı","Örnek"],"fa":["الگو","مثال"]},"rows":[["agree to + verb","The client agreed to share his laundry test."],["ask + person + (not) to + verb","He asked us not to publish any prices."],["recommend + -ing","He recommended adding the laundry test."]]},"wrong":"He asked us don't publish any prices.","right":"He asked us not to publish any prices.","blank":{"sentence":"The client asked us ___ any prices in the text.","word":"not to publish","distractors":["don't publish","to not publishing"]},"wrong2":"The client agreed sharing his laundry test.","right2":"The client agreed to share his laundry test.","blank2":{"sentence":"He recommended ___ the laundry test to the story.","word":"adding","distractors":["to add","add"]},"useIn":{"en":"B2: in your case study, report what the client agreed or asked with agree to, ask... not to or recommend -ing.","tr":"B2: vaka çalışmanda müşterinin neyi kabul ettiğini ya da ne istediğini agree to, ask... not to veya recommend -ing ile aktar.","fa":"B2: در کیس استادی‌ات، چیزی را که مشتری پذیرفته یا خواسته با agree to، ask... not to یا recommend -ing گزارش کن."},"exitItem":{"from":"mkt-11","kind":"blank","prompt":"The hotel group agreed ___ its name in the case study.","options":["using","to use","use"],"correct":1},"expParts":{"tryFrom":"blank","rule":[{"en":"agree to + verb.","tr":"agree to + fiil.","fa":"بعد از agree اول to و بعد فعل می‌آید.","ex":"The client agreed to share his test."},{"en":"ask + person + (not) to + verb.","tr":"ask + kişi + (not) to + fiil.","fa":"بعد از ask اول شخص، بعد to (یا not to) و فعل می‌آید.","ex":"He asked us not to publish prices."},{"en":"recommend + -ing.","tr":"recommend + -ing.","fa":"recommend + ‎-ing.","ex":"He recommended adding the test."}],"test":{"en":"Learn each verb with its partner: agree to, ask someone (not) to, recommend -ing.","tr":"Her fiili eşiyle birlikte öğren: agree to, ask someone (not) to, recommend -ing.","fa":"هر فعل را با همراهش یاد بگیر: agree to، ask someone (not) to، recommend -ing."},"contrast":{"en":"Turkish \"fiyatları yayınlamamamızı istedi\" and Persian «از ما خواست قیمت‌ها را منتشر نکنیم» put the negative inside the verb, so learners write \"asked us don't publish\". English uses not to + verb.","tr":"Türkçede \"fiyatları yayınlamamamızı istedi\" derken olumsuzluk fiilin içindedir; bu yüzden \"asked us don't publish\" yazılır. İngilizce not to + fiil kullanır.","fa":"در فارسی «از ما خواست قیمت‌ها را منتشر نکنیم» منفی را داخل فعل می‌آورد؛ برای همین می‌نویسیم «asked us don't publish». انگلیسی not to و فعل به کار می‌برد."}},"errorWatch":[{"find":["asked us don't","asked us to don't","asked us not publish","agreed sharing","agreed using","recommended to add","recommended to use"],"fix":{"en":"agree to + verb; ask someone not to + verb; recommend + -ing.","tr":"agree to + fiil; ask someone not to + fiil; recommend + -ing.","fa":"agree to با فعل؛ ask someone not to با فعل؛ recommend با -ing."}}]},"vocab":{"id":"c-mkt-11-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-11","goals":["career"],"title":{"en":"Case Studies","tr":"Vaka Çalışmaları","fa":"کیس استادی"},"cards":[{"word":"case study","sentence":"A good case study tells one client's real story.","meaning":{"en":"A short story about how a customer used your product.","tr":"vaka çalışması","fa":"کیس استادی؛ مطالعه‌ی موردی"}},{"word":"client","sentence":"The hotel group is now our biggest hotel client.","meaning":{"en":"A company or person that buys a service or product from you.","tr":"müşteri","fa":"مشتری؛ کارفرما"}},{"word":"challenge","sentence":"The challenge was simple: towels went hard too quickly.","meaning":{"en":"The problem the client had before.","tr":"zorluk, sorun","fa":"چالش"}},{"word":"solution","sentence":"Every case study needs a challenge and a solution.","meaning":{"en":"The answer to a problem.","tr":"çözüm","fa":"راه‌حل"}},{"word":"outcome","sentence":"We will add the outcome when the hotels have measured it.","meaning":{"en":"The result.","tr":"sonuç","fa":"نتیجه"}},{"word":"quote","sentence":"Use the client's exact words in the quote.","meaning":{"en":"Someone's exact words, written down.","tr":"alıntı","fa":"نقل‌قول"}},{"word":"testimonial","sentence":"A short testimonial from a real client is worth a page of adjectives.","meaning":{"en":"A statement from a customer saying they are happy with a product.","tr":"müşteri referansı, tavsiye sözü","fa":"رضایت‌نامه‌ی مشتری (تستیمونیال)"}},{"word":"approve","sentence":"The client must approve every word before we publish.","meaning":{"en":"To officially say yes to something.","tr":"onaylamak","fa":"تأیید کردن"}},{"word":"confidential","sentence":"Prices in the contract are confidential.","meaning":{"en":"Secret; not for the public.","tr":"gizli","fa":"محرمانه"}},{"word":"permission","sentence":"We have the client's permission to use the hotels' name.","meaning":{"en":"When someone says you are allowed to do something.","tr":"izin","fa":"اجازه"}}]},"judge":{"id":"c-mkt-11-j","course":"marketing","unit":"mkt-11","type":"judge","title":{"en":"Can this go in the story?","tr":"Bu hikâyeye girebilir mi?","fa":"این می‌تواند در داستان بیاید؟"},"prompt":"Four sentences for a customer story about a bakery chain and an invoice app. The owner agreed to the story, but no prices may appear.","parts":["The customer really said it or agreed to it","No confidential numbers","Shows something real"],"instruction":{"en":"Tap what each sentence does well. A sentence you can publish has all three.","tr":"Her cümlenin iyi yaptığı şeylere dokun. Yayımlanabilecek cümlede üçü de vardır.","fa":"روی کارهایی که هر جمله درست انجام داده بزن. جمله‌ای که منتشر می‌شود هر سه را دارد."},"items":[{"by":"AI tool","answer":"The bakery saved 40% on costs after switching to our app.","present":[],"fix":{"en":"Nobody measured this. An invented result can destroy a customer's trust. Remove it.","tr":"Bunu kimse ölçmedi. Uydurulmuş bir sonuç müşterinin güvenini yok edebilir. Çıkar.","fa":"کسی این را اندازه نگرفته. نتیجه‌ی ساختگی می‌تواند اعتماد مشتری را از بین ببرد. حذفش کن."}},{"by":"AI tool","answer":"\"It's the best app in the world,\" says the owner.","present":[],"fix":{"en":"She never said this. Never put words in a customer's mouth; use her real words.","tr":"Bunu hiç söylemedi. Müşterinin ağzına söz koyma; gerçek sözlerini kullan.","fa":"او هرگز این را نگفته. حرف در دهان مشتری نگذار؛ کلمه‌های واقعی‌اش را بیاور."}},{"by":"Sales colleague","answer":"The bakery pays just 12 euros a month.","present":["Shows something real"],"fix":{"en":"True, but confidential: she agreed only if no prices appear. Remove it.","tr":"Doğru ama gizli: yalnızca fiyat geçmemesi şartıyla kabul etti. Çıkar.","fa":"درست است ولی محرمانه: فقط به این شرط قبول کرده که قیمتی نیاید. حذفش کن."}},{"by":"Good model","answer":"\"I stopped doing invoices on Sundays,\" says Lena Aksoy, owner.","present":["The customer really said it or agreed to it","No confidential numbers","Shows something real"],"fix":null}]},"writing":{"id":"c-mkt-11-w","title":{"en":"A customer story","tr":"Bir müşteri hikâyesi","fa":"یک داستان مشتری"},"course":"marketing","unit":"mkt-11","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"mkt-final-6","prompt":{"en":"Write a customer story for approval (100-120 words) about your own customer, or from these notes: a bakery chain with four shops; the owner, Lena Aksoy, had spent 10 hours a month on invoices; she tried an invoice app in one shop for a month; then all four shops joined; invoice time fell to 2 hours; her words: \"I stopped doing invoices on Sundays.\" Use a title, then challenge, test, decision and next. No prices.","tr":"Kendi müşterin ya da şu notlar hakkında onay için bir müşteri hikâyesi yaz (100-120 kelime): dört şubeli bir fırın zinciri; sahibi Lena Aksoy ayda 10 saatini faturalara harcıyordu; bir fatura uygulamasını bir şubede bir ay denedi; sonra dört şubenin hepsi katıldı; fatura süresi 2 saate düştü; sözleri: \"I stopped doing invoices on Sundays.\" Bir başlık, sonra sorun, deneme, karar ve sonraki adım. Fiyat yok.","fa":"برای مشتری خودت، یا از روی این یادداشت‌ها، یک داستان مشتری برای تأیید بنویس (۱۰۰ تا ۱۲۰ کلمه): یک زنجیره‌ی نانوایی با چهار شعبه؛ صاحبش، Lena Aksoy، ماهی ۱۰ ساعت وقت صدور فاکتور می‌کرد؛ یک اپلیکیشن فاکتور را یک ماه در یک شعبه امتحان کرد؛ بعد هر چهار شعبه از آن استفاده کردند؛ زمان صدور فاکتور به ۲ ساعت رسید؛ حرف خودش: «I stopped doing invoices on Sundays.» یک تیتر، بعد چالش، آزمایش، تصمیم و قدم بعدی. بدون قیمت."},"model":"Four bakeries, no more invoice Sundays\n\nThe challenge: Before she tried the app, Lena Aksoy had spent 10 hours a month on invoices for her four bakeries. She had done most of them on Sundays.\n\nThe test: She ran one shop on the app for a month and counted the hours.\n\nThe decision: After that month, all four shops joined, and her invoice time fell to 2 hours a month.\n\nWhat comes next: The team will add supplier invoices in the autumn, and we will share those results when she has measured them.\n\n\"I stopped doing invoices on Sundays,\" says Lena Aksoy, owner.","frame":"___\n\nThe challenge: Before ___, ___ had ___.\n\nThe test: ___.\n\nThe decision: ___.\n\nWhat comes next: ___.\n\n\"___,\" says ___.","words":[{"word":"had spent"},{"word":"the test"},{"word":"says"}],"minWords":90,"minSentences":6,"rubric":["Task done: title, challenge, test, decision, next, one real quote","Organised: the four parts in order, each short","Language: past perfect for the background; past simple for the events","Tone: plain and exact; no invented results, no prices"],"rubricI18n":{"tr":["Görev: başlık, sorun, deneme, karar, sonraki adım, gerçek bir alıntı","Düzen: dört bölüm sırayla, her biri kısa","Dil: arka plan için past perfect; olaylar için past simple","Üslup: sade ve net; uydurma sonuç yok, fiyat yok"],"fa":["کامل بودن کار: تیتر، چالش، آزمایش، تصمیم، قدم بعدی، یک نقل‌قول واقعی","نظم: چهار بخش به ترتیب و هر کدام کوتاه","زبان: ماضی بعید برای پیش‌زمینه؛ گذشته‌ی ساده برای اتفاق‌ها","لحن: ساده و دقیق؛ بدون نتیجه‌ی ساختگی و قیمت"]}},"speaking":{"id":"mkt-11","course":"marketing","unit":"mkt-11","topic":{"en":"Asking a customer for approval","tr":"Müşteriden onay istemek","fa":"تأیید گرفتن از مشتری"},"warmup":{"en":"Would you let a company use your name? What would you want to check first?","tr":"Bir şirketin adını kullanmasına izin verir miydin? Önce neyi kontrol etmek isterdin?","fa":"اجازه می‌دهی شرکتی از اسمت استفاده کند؟ اول چه چیزی را می‌خواهی بررسی کنی؟"},"questions":[{"en":"On a call, ask a customer if you can tell their story. Say what you would like to write.","tr":"Bir görüşmede müşteriye hikâyesini anlatıp anlatamayacağını sor. Ne yazmak istediğini söyle.","fa":"در یک تماس از مشتری بپرس می‌توانی داستانش را بگویی یا نه. بگو می‌خواهی چه بنویسی."},{"en":"The customer says: \"No prices, and I want to read every word.\" Answer.","tr":"Müşteri diyor ki: \"No prices, and I want to read every word.\" Cevap ver.","fa":"مشتری می‌گوید: «No prices, and I want to read every word.» جواب بده."},{"en":"The customer changes your favourite line. Accept it politely and agree a date.","tr":"Müşteri en sevdiğin satırı değiştiriyor. Kibarca kabul et ve bir tarihte anlaş.","fa":"مشتری خطی را که بیشتر دوست داری عوض می‌کند. مؤدبانه بپذیر و روی یک تاریخ توافق کن."}],"followups":[{"en":"Now ask for approval from a real customer or colleague you work with.","tr":"Şimdi birlikte çalıştığın gerçek bir müşteriden ya da iş arkadaşından onay iste.","fa":"حالا از یک مشتری یا همکار واقعی که با او کار می‌کنی تأیید بخواه."}],"expressions":[{"phrase":"Would you be happy for us to...?","meaning":{"en":"Asks for permission politely.","tr":"Kibarca izin ister.","fa":"مؤدبانه اجازه می‌خواهد."}},{"phrase":"You'll see every word before it goes out.","meaning":{"en":"Promises approval.","tr":"Onay sözü verir.","fa":"قول می‌دهد متن را برای تأیید بفرستد."}},{"phrase":"Of course, it's your name.","meaning":{"en":"Accepts a change without arguing.","tr":"Tartışmadan değişikliği kabul eder.","fa":"بدون بحث تغییر را می‌پذیرد."}}],"model":"Your month with the app was so clear that I'd like to tell other shops about it. Would you be happy for us to write a short story about your bakeries? You'll see every word before it goes out, and we won't publish any prices. If you change a line, of course, it's your name. Could you send me your changes by Thursday?","selfCheck":[{"en":"I asked for permission clearly.","tr":"Açıkça izin istedim.","fa":"روشن اجازه خواستم."},{"en":"I promised approval and no prices.","tr":"Onay ve fiyat olmaması sözü verdim.","fa":"قول دادم متن را برای تأیید بفرستم و قیمت نیاورم."},{"en":"I agreed a date.","tr":"Bir tarihte anlaştım.","fa":"روی یک تاریخ توافق کردم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم را در زمان تعیین‌شده تمام کردم."}]},"exit":{"id":"c-mkt-11-x","course":"marketing","unit":"mkt-11","type":"exit","items":[{"from":"mkt-11","kind":"blank","prompt":"By the time the contract was signed, the lawyers ___ it three times.","options":["have read","had read","had reading"],"correct":1,"point":2},{"from":"mkt-11","kind":"mcq","prompt":"What must happen before a customer story goes out?","options":["The customer approves the final text.","It gets 100 likes.","The AI tool checks it."],"correct":0,"point":1},{"from":"mkt-11","kind":"mcq","prompt":"You have no measured result yet. What do you write?","options":["A likely figure of 30%","The test the customer ran, and that results will follow","\"Huge savings\""],"correct":1,"point":1},{"from":"mkt-10","kind":"blank","prompt":"Since March, two more customers ___ for samples.","options":["asked","have asked","are asking"],"correct":1},{"from":"mkt-8","kind":"mcq","prompt":"An email got 600 likes and 5 sign-ups. The goal was sign-ups. How do you report it?","options":["A big success: 600 likes!","Weak on the goal: 5 sign-ups, despite the likes.","We cannot tell."],"correct":1},{"from":"mkt-4","kind":"blank","prompt":"The customer suggested ___ her exact words.","options":["to use","use","using"],"correct":2}]},"explain":{"id":"c-mkt-11-e","course":"marketing","unit":"mkt-11","type":"explain","level":"B1","title":{"en":"Writing the customer story","tr":"Müşteri hikâyesi yazmak","fa":"نوشتن داستان مشتری"},"objective":{"en":"After this lesson, you can write a customer story from real facts and get it approved.","tr":"Bu dersin sonunda gerçek bilgilerden bir müşteri hikâyesi yazabilecek ve onaylatabileceksin.","fa":"بعد از این درس می‌توانی از روی واقعیت‌ها یک داستان مشتری بنویسی و تأییدش را بگیری."},"hook":{"en":"A customer story is proof that your product worked, told with real numbers and the customer's own words. One invented line can destroy that proof, so you check every fact and get approval.","tr":"Müşteri hikâyesi, ürününün işe yaradığının gerçek rakamlar ve müşterinin kendi sözleriyle anlatılan kanıtıdır. Uydurulmuş tek bir satır bu kanıtı yok edebilir; bu yüzden her bilgiyi kontrol eder ve onay alırsın.","fa":"داستان مشتری مدرکی است که محصولت جواب داده، با عددهای واقعی و کلمه‌های خود مشتری. یک خط ساختگی می‌تواند این مدرک را از بین ببرد؛ پس هر واقعیت را بررسی می‌کنی و تأیید می‌گیری."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"Four parts and real words","tr":"Dört bölüm ve gerçek sözler","fa":"چهار بخش و کلمه‌های واقعی"},"steps":[{"en":"Challenge: what was wrong before you arrived? Readers with the same problem see themselves here.","tr":"Sorun: Sen gelmeden önce ne yanlıştı? Aynı sorunu yaşayan okurlar kendilerini burada görür.","fa":"چالش: قبل از آمدن تو چه مشکلی بود؟ مخاطب‌هایی که همین مشکل را دارند خودشان را اینجا می‌بینند.","ex":"A bakery had spent 10 hours a month on invoices."},{"en":"Test: how did the customer try you first? A small first step makes buying feel safe.","tr":"Deneme: Müşteri seni önce nasıl denedi? Küçük bir ilk adım, satın almayı güvenli hissettirir.","fa":"آزمایش: مشتری اول چطور امتحانت کرد؟ یک قدم کوچک اول، خرید را کم‌خطر نشان می‌دهد.","ex":"They ran one shop on the app for a month."},{"en":"Decision and result: use only what was really measured, because someone may ask how.","tr":"Karar ve sonuç: Yalnızca gerçekten ölçüleni kullan, çünkü biri nasıl ölçüldüğünü sorabilir.","fa":"تصمیم و نتیجه: فقط چیزی را بیاور که واقعاً اندازه گرفته شده، چون ممکن است کسی بپرسد چطور.","ex":"Three more shops joined; invoice time fell to 2 hours."},{"en":"Quote: real words, full name and job, approved in writing. A real name makes it believable.","tr":"Alıntı: gerçek sözler, tam ad ve görev, yazılı onaylı. Gerçek bir ad, alıntıyı inandırıcı kılar.","fa":"نقل‌قول: کلمه‌های واقعی، نام کامل و سمت، با تأیید کتبی. اسم واقعی حرف را باورپذیر می‌کند.","ex":"\"I stopped doing invoices on Sundays.\""}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"The background of a story: the past perfect (had + past participle)","tr":"Bir hikâyenin arka planı: past perfect (had + üçüncü hâl)","fa":"پیش‌زمینه‌ی داستان: ماضی بعید (had با اسم مفعول)"},"steps":[{"en":"Main events of the story: past simple.","tr":"Hikâyenin ana olayları: past simple.","fa":"برای اتفاق‌های اصلی داستان، گذشته‌ی ساده می‌آید.","ex":"They chose us in March."},{"en":"Earlier background: had + past participle.","tr":"Daha önceki arka plan: had + üçüncü hâl.","fa":"برای پیش‌زمینه‌ی قبل‌تر، had و اسم مفعول می‌آید.","ex":"They had bought from three suppliers."},{"en":"Use it only where the order matters.","tr":"Sadece sıralamanın önemli olduğu yerde kullan.","fa":"فقط جایی به کارش ببر که ترتیب مهم است.","ex":"They had tested the samples before they signed."}],"table":{"headers":{"en":["Earlier (background): past perfect","Main event: past simple"],"tr":["Daha önce (arka plan): past perfect","Ana olay: past simple"],"fa":["قبل‌تر (پیش‌زمینه): ماضی بعید","اتفاق اصلی: گذشته‌ی ساده"]},"rows":[["The hotels had bought towels from three suppliers.","Then they chose us."],["Housekeeping had complained for years.","So the buyer looked for a new supplier."],["They had washed the samples fifty times.","Then they signed the contract."]]},"tip":{"en":"Turkish has the same idea in \"-mişti\" (almışlardı) and Persian in the past perfect («خریده بودند»), so the meaning is familiar. The trap is the English form: had + past participle, never had + base verb.","tr":"Türkçede aynı anlam \"-mişti\" ile verilir (almışlardı), yani fikir tanıdık. Tuzak İngilizce biçimde: had + üçüncü hâl, asla had + yalın fiil değil.","fa":"فارسی همین معنا را با ماضی بعید دارد («خریده بودند»)، پس ایده آشناست. تله در شکل انگلیسی است: had با اسم مفعول، هرگز had با فعل ساده."},"wrong":"Before she found us, she tried three other brands.","right":"Before she found us, she had tried three other brands."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Getting a customer story approved","tr":"Müşteri hikâyesini onaylatmak","fa":"برای داستان مشتری تأیید بگیر"},"body":{"en":"Ask early, while the work is fresh. Agree what stays out, such as prices. Send the final text and say where it will appear. If the customer can't be named, describe the sector instead. Keep the written approval.","tr":"Erken sor, iş tazeyken. Fiyatlar gibi nelerin metne girmeyeceğinde anlaş. Son metni gönder ve nerede yayımlanacağını söyle. Müşterinin adı verilemiyorsa sektörünü anlat. Yazılı onayı sakla.","fa":"زود بپرس، وقتی کار هنوز تازه است. درباره‌ی چیزهایی که نباید بیایند، مثل قیمت، توافق کن. متن نهایی را بفرست و بگو کجا منتشر می‌شود. اگر نمی‌شود اسم مشتری را آورد، حوزه‌ی کارش را توصیف کن. تأیید کتبی را نگه دار."},"phrases":[{"phrase":"Would you be happy for us to...?","meaning":{"en":"Asks for permission politely.","tr":"Kibarca izin ister.","fa":"مؤدبانه اجازه می‌خواهد."}},{"phrase":"You'll see every word before it goes out.","meaning":{"en":"Promises approval.","tr":"Onay sözü verir.","fa":"قول می‌دهد متن را برای تأیید بفرستد."}},{"phrase":"Of course, it's your name.","meaning":{"en":"Accepts a change without arguing.","tr":"Tartışmadan değişikliği kabul eder.","fa":"بدون بحث تغییر را می‌پذیرد."}},{"phrase":"testimonial","meaning":{"en":"A statement from a customer saying they are happy with a product.","tr":"müşteri referansı, tavsiye sözü","fa":"رضایت‌نامه‌ی مشتری (تستیمونیال)"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Replace an invented line","tr":"Uydurma bir satırı değiştir","fa":"یک خط ساختگی را عوض کن"},"item":"The bakery saved 40% on costs. \"It's the best app in the world,\" says the owner. Notes: nobody measured costs; before the app, 10 hours a month on invoices; her real words: \"I stopped doing invoices on Sundays.\"","answer":"Before they tried the app, the owner had spent 10 hours a month on invoices. \"I stopped doing invoices on Sundays,\" she says.","walk":[{"en":"Check each number: who measured the 40%? Nobody, so it goes.","tr":"Her rakamı kontrol et: %40'ı kim ölçtü? Kimse, o yüzden çıkıyor.","fa":"هر عدد را بررسی کن: ۴۰ درصد را چه کسی اندازه گرفته؟ هیچ‌کس، پس حذفش کن."},{"en":"Check the quote: did she say it? Use her real words.","tr":"Alıntıyı kontrol et: bunu söyledi mi? Gerçek sözlerini kullan.","fa":"نقل‌قول را بررسی کن: این را گفته؟ کلمه‌های واقعی‌اش را بیاور."},{"en":"Add the before: had + past participle gives the background.","tr":"Öncesini ekle: had + past participle arka planı verir.","fa":"وضعیت قبل را اضافه کن: had و اسم مفعول پیشینه را نشان می‌دهد."}]},"quick":{"prompt":"Before you publish a customer story, the customer must ___ it.","options":["approve","design","pay for"],"correct":0,"why":{"en":"approve: it carries their name, so they check every word before it goes out.","tr":"approve: onların adını taşıyor, bu yüzden yayımlanmadan önce her kelimeyi kontrol ederler.","fa":"جواب approve است: اسم خودشان پای آن است، پس قبل از انتشار تک‌تک کلمه‌ها را بررسی می‌کنند."}},"remember":{"en":"Before you send it, ask: did the customer really say it, and did someone really measure it? You can now write a customer story from real facts and get it approved.","tr":"Göndermeden önce sor: Bunu müşteri gerçekten söyledi mi, biri gerçekten ölçtü mü? Artık gerçek bilgilerden bir müşteri hikâyesi yazabilir ve onaylatabilirsin.","fa":"پیش از فرستادن بپرس: مشتری واقعاً این را گفته و کسی واقعاً آن را اندازه گرفته؟ حالا می‌توانی از روی واقعیت‌ها داستان مشتری بنویسی و تأییدش را بگیری."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Reporting what a client agreed: agree to, ask someone not to, recommend -ing","tr":"Müşterinin neyi kabul ettiğini aktarmak: agree to, ask someone not to, recommend -ing","fa":"گزارش توافق‌های مشتری: agree to، ask someone not to، recommend -ing"},"steps":[{"en":"agree to + verb.","tr":"agree to + fiil.","fa":"بعد از agree اول to و بعد فعل می‌آید.","ex":"The client agreed to share his test."},{"en":"ask + person + (not) to + verb.","tr":"ask + kişi + (not) to + fiil.","fa":"بعد از ask اول شخص، بعد to (یا not to) و فعل می‌آید.","ex":"He asked us not to publish prices."},{"en":"recommend + -ing.","tr":"recommend + -ing.","fa":"recommend + ‎-ing.","ex":"He recommended adding the test."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Yapı","Örnek"],"fa":["الگو","مثال"]},"rows":[["agree to + verb","The client agreed to share his laundry test."],["ask + person + (not) to + verb","He asked us not to publish any prices."],["recommend + -ing","He recommended adding the laundry test."]]},"body":{"en":"B2: in your case study, report what the client agreed or asked with agree to, ask... not to or recommend -ing.","tr":"B2: vaka çalışmanda müşterinin neyi kabul ettiğini ya da ne istediğini agree to, ask... not to veya recommend -ing ile aktar.","fa":"B2: در کیس استادی‌ات، چیزی را که مشتری پذیرفته یا خواسته با agree to، ask... not to یا recommend -ing گزارش کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
